parts=[];page=0
def add(title,body,kicker='22NFT / BUILD STUDY',cls=''):
 global page
 page+=1;parts.append(f'<section class="page {cls}" id="p{page}"><div class="kicker">{esc(kicker)}</div><h2>{title}</h2>{body}<div class="folio">ANDREW ROSE · ALITA 22NFT · 07 OCT 2026 · {page:02d}</div></section>')
add('ALITA 22NFT<br><span class="light">Sunset Noir.</span>', '<p class="lede">A solo mobile editing office. Preserved desk and lift bed. Tail power. Six-panel solar. Two laundry studies.</p><div class="metrics"><div class="metric"><b>1,650 W</b><span>ROOF NAMEPLATE / SIX PARALLEL</span></div><div class="metric"><b>10.24 kWh</b><span>NOMINAL / TWO B4810 PACKS</span></div><div class="metric"><b>18K BTU</b><span>DUCTED AC HEAT PUMP</span></div><div class="metric"><b>A / B</b><span>LAUNDRY LOCATION OPEN</span></div></div><img class="cover-photo" src="../renders/01.jpg"><p class="small">A source-grounded design visualization. Component envelopes are researched; the production coach, roof, tail and cabinet measurements are not surveyed. No installation approval is implied.</p>',kicker='ANDREW ROSE / MOBILE STUDIO / V01')
add('One current build record.', '''<div class="grid"><div><h3>Confirmed user direction</h3><p>Rear desk, drawer pedestal, lift bed and garage remain. Keep the factory kitchen and forward couch where practical. Dry bath and cab-over sleeping are retained.</p><p>RV5 + two B4810 packs at the tail underbody; six Callsun 275 W panels parallel; two Victron driving chargers; onboard generator with automatic start; Furrion ducted 18K heat pump; Starlink; vented Splendide with A/B placement.</p><p>Quiet work and sleep, camera/luggage storage and economical improvements remain the purpose.</p></div><div><h3>Three evidence levels</h3><p><span class="tag">Confirmed</span> Published manufacturer value for the exact named component or OEM year. This does not verify fit to a selected VIN.</p><p><span class="tag">Credible</span> Dealer/historical guide or unresolved published data, including the unusually high panel mass.</p><p><span class="tag">ESTIMATE</span> Reconstructed dimensions, positions, routes, costs/energy scenarios and modeling assumptions. Every physical installation coordinate in this book is in this category.</p><div class="note">Exact production year, VIN and actual OCCC remain unknown. Current OEM 2027 22NF is the dimensional reference; dealer 22NFT alias is retained in project naming.</div></div></div>''')
add('Explore the complete model.', '''<div class="viewer-wrapper"><div class="controls">'''+''.join(f'<label><input type="checkbox" data-layer="{n}" checked> {label}</label>' for n,label in [('shell','Shell'),('power','Power'),('solar','Solar / roof'),('laundry_A','Laundry A'),('laundry_B','Laundry B'),('interior','Interior'),('chassis','Chassis'),('tow_car','Tow car')])+'''<label><input type="checkbox" data-case checked> Tail case / lid</label></div><div class="controls">'''+''.join(f'<button data-camera="{n}">{t}</button>' for n,t in [('exterior','Exterior'),('roof','Roof'),('interior','Interior'),('power','Power cutaway'),('rear','Tail')])+'''</div><div id="viewer" aria-label="Interactive Alita model"></div><div id="viewer-status">Loading source model…</div><p class="small">Drag to orbit · wheel/pinch to zoom · right drag to pan. A and B are exclusive. Power/tail presets open the enclosure and hide cabin layers; exterior restores them. The tail-case toggle controls walls/lid. All component placements ESTIMATE. Procedural oak grain is visible in Cycles renders; GLB uses material approximations.</p></div><img class="print-preview" src="../renders/05-annotated.jpg"><p class="small">The interactive HTML edition embeds its model and viewer code. Open the standalone HTML in a browser for orbit and layer controls. This print edition carries the annotated power view.</p>''',kicker='INTERACTIVE / THREE.JS + GLB')
for v,(title,caption) in cap.items():
 add(title,f'<img src="../renders/{v+"-annotated" if v in ["02","11"] else v}.jpg" alt="{esc(title)}"><p class="caption">{esc(caption)}</p>',kicker=f'RENDER {v} / CYCLES CPU / 1920 × 1080',cls='render')
 if v in ['03','04','05','08','09','10']:
  add(title+' / annotated',f'<img src="../renders/{v}-annotated.jpg" alt="Annotated {esc(title)}"><p class="caption">{esc(caption)}</p>',kicker=f'RENDER {v} / MEASUREMENT & SERVICE STUDY',cls='render')
add('What changed in the numbers.', f'''<table><tr><th>Earlier working figure</th><th>Current finding</th><th>Implication</th></tr><tr><td>~1,200 W roof</td><td>6 × 275 W = 1,650 W</td><td>Higher nameplate; current/roof/payload gates remain.</td></tr><tr><td>~15.6 ft for six panels</td><td>15.50 ft with five 1 in panel gaps; 18.04 ft including modeled 29.5 in A/C band and six gaps</td><td>15.6 ft is credible for bare panel rows only. Estimated 220 in usable roof leaves ~3.54 in total longitudinal slack before service setbacks.</td></tr><tr><td>+294 rear / −91 front</td><td>Battery pair alone at ~80 in lever reproduces +293.95 / −91.15 lb. Complete tail assembly in current model: +403.45 / −114.79 lb.</td><td>Old pair-only estimate omits RV5, enclosure/mounts and cables; actual CG must be measured.</td></tr><tr><td>48 V DC A/C concept</td><td>Chosen Furrion is AC powered, 77.16 lb gross</td><td>House inverter supplies HVAC. Factory removed A/C mass unknown.</td></tr><tr><td>Roof panel mass unspecified</td><td>Website 65.65 lb each / 393.9 lb for six</td><td>High-priority net-mass verification; roof and payload engineering may change feasibility.</td></tr></table><div class="note">The calculations implement your chosen components; they do not quietly change hardware to make a diagram fit. If measurements reject a location or electrical interface, that conflict stays open.</div>''')
add('Electrical compatibility gates.', '''<table><tr><th>Path</th><th>Research result</th><th>Required resolution</th></tr><tr><td>Six parallel → RV5</td><td>21.29 V / 77.52 A operating; 25.26 V / 82.14 A Isc. Published RV5 PV limit is 50 A / 12–50 V.</td><td>A common six-panel branch exceeds the published input current limit. Confirm independent input ratings and clipping/overcurrent rules; a split 3+3 parallel arrangement is only a proposed alternative.</td></tr><tr><td>Series alternative</td><td>Two panels Voc 50.52 V before cold correction</td><td>Already exceeds published 50 V. Do not silently rewire in series.</td></tr><tr><td>Orion → house system</td><td>12/48-8 Smart output 40–60 V; pair 720 W at 40°C.</td><td>Do not feed 50 V-max PV input. External B4810 charge connection needs documented BMS/terminal permission; Ford CCP/current/thermal constraints need current-year guide.</td></tr><tr><td>Generator → RV5</td><td>OEM 4 kW; RV5 charger up to 5 kW</td><td>Limit charging for actual generator rating and concurrent AC loads. Verify transfer, neutral/ground and AGS start connector/SOC integration.</td></tr><tr><td>House → HVAC/laundry</td><td>Furrion AC heat pump and Splendide 120 V / 11 A</td><td>Dedicated appliance circuit, measured HVAC draw, load management and 12 V house distribution verification required.</td></tr></table><p>AGS priority remains solar → battery → generator backup, with quiet-hour inhibit and a reserve set from actual loads. Driving alternator charging is separate; stationary chassis engine auto-start is excluded.</p>''')
add('Tail load: the actual math.', f'''<p class="formula">Δrear = mass × distance aft of front axle / 178 in<br>Δfront = mass − Δrear</p><p>For a component behind the rear axle, rear load rises by more than its mass and the front axle unloads. The estimate is static, longitudinal and level-ground; it does not model suspension, corner loads, braking or mounting stresses.</p><table><tr><th>Tail item</th><th>Mass lb</th><th>CG aft front axle in</th><th>Δfront lb</th><th>Δrear lb</th></tr>'''+''.join(f'<tr><td>{esc(r["item"])}</td><td>{r["mass_lb"]:.2f}</td><td>{r["x_from_front_axle_in"]:.2f}</td><td>{r["front_lb"]:+.2f}</td><td>{r["rear_lb"]:+.2f}</td></tr>' for r in A['components'][:4])+'''<tr><td>Complete modeled tail assembly</td><td>288.66</td><td>Aggregate ~248.8 / ESTIMATE</td><td>−114.79</td><td>+403.45</td></tr></table><div class="note">The ~45.5 × 37 × 9.5 in envelope has barely enough bare-envelope space; manufacturer cooling, orientation and connector clearances are unknown. Modeled 10.2 in clearance / 5.9° departure angle is a concern to measure, not a qualified design.</div>''')
add('Gross build weight, not remaining payload.', '<table><tr><th>Component</th><th>Added lb</th><th>Δfront lb</th><th>Δrear lb</th><th>Qualification</th></tr>'+''.join(f'<tr><td>{esc(r["item"])}</td><td>{r["mass_lb"]:.2f}</td><td>{r["front_lb"]:+.2f}</td><td>{r["rear_lb"]:+.2f}</td><td>{esc(r["note"])}</td></tr>' for r in A['components'][4:])+'''</table><p>Using only one laundry option and its support allowance, gross additions are <strong>998.64 lb</strong>. A: −40.00 front / +1,038.64 rear. B: −79.66 front / +1,078.30 rear. Subtract actual removed stock A/C, cabinets and existing equipment at their measured centers before calling this net load.</p><p class="small">Factory GAWR: 4,630 lb front / 7,275 lb rear. GVWR: 11,000 lb. Neither limit proves remaining capacity without actual base axle weights and OCCC. Fuel/water, driver, gear, luggage, scooter and tow hardware must be included separately.</p>''')
add('Laundry: A versus B.', '''<table><tr><th>Comparison</th><th>A / bath side</th><th>B / rear garage</th></tr><tr><td>Space displaced</td><td>Bath-adjacent storage; ~3.69 sq ft machine footprint / ~4.52 sq ft proposed bay. Preserve dry shower/toilet.</td><td>Passenger rear gear bay; same footprint/bay. Less room for cases, light stands, luggage/scooter staging.</td></tr><tr><td>Loading / service</td><td>Door aisle and bath slider may conflict; ~40.5 in open-depth envelope and pull-out route must be taped.</td><td>Desk chair, drawers, rear hatch and gear route need full door-sweep check. Bed lowered clearance unresolved.</td></tr><tr><td>Water / drain</td><td>Estimated 2–3 m hot/cold/drain routing crossing protected floor cavity toward galley gray branch.</td><td>Estimated 2–4 m toward galley branch. No claim either branch accepts 7 gpm discharge.</td></tr><tr><td>Dryer vent</td><td>Estimated 0.3–0.8 m dedicated 4 in exterior metal duct, if permitted wall exit exists.</td><td>Estimated 0.3–0.8 m rear-side exit, with case/bed/door and window separation checked.</td></tr><tr><td>Weight position</td><td>Appliance 148 lb near rear axle: ~−0.77 front / +148.77 rear.</td><td>Appliance 148 lb farther aft: ~−36.78 front / +184.78 rear. With 15 lb support/lines, B shifts ~39.66 lb more to rear than A.</td></tr><tr><td>Desk / sleep noise</td><td>Some distance from desk; structure-borne vibration still reaches bed. Bath-adjacent activity can affect aisle.</td><td>Closest to desk and raised/low bed. Most likely to interfere with quiet editing/sleep; no acoustic test yet.</td></tr></table><div class="note">No laundry location is selected. A keeps rear gear volume but risks bath/aisle fit; B follows the earlier opposite-desk direction but carries greater rear-load and bed/noise conflicts. Render both, measure both.</div>''')
add('Laundry installation envelope.', '''<div class="grid"><div><h3>Manufacturer requirements</h3><p>23.5 W × 22.625 D × 33–33.375 H in; 148 lb. Provide ≥280 lb solid level floor support, proper anchoring and 1 in front/back case clearances (0 side minimum).</p><p>Dedicated 120 V 15 A circuit; rated 11 A / 1,300 W. Vented drying requires a dedicated 4 in exterior metal duct and permitted duct length/bends, plus ≥8 sq in enclosure makeup air.</p><p>Drain standpipe ≥1.25 in ID, capacity ≥7 gpm. Standpipe top 25–34 in above appliance bottom; hose outlet/air break per installation manual. Do not seal hose into an unvented drain.</p></div><div><h3>Proposed plumbing, not verified</h3><p>Individual shutoff tees at kitchen hot/cold supplies; protected serviceable hose routes to laundry bay; independent trapped standpipe draining to a verified kitchen gray branch.</p><p>Rendered routes are topology. Underfloor penetrations, branch slope/venting, freeze protection, trap cleanout, tank response and exterior dryer outlet need a measured installation plan.</p><p>The appliance door-open envelope is ~40.5 in from the datasheet diagram, marked Credible for access planning; verify actual appliance and loading posture.</p><div class="note">Shown with lift bed raised. Verify every intermediate and lowered position, not only a static open bay.</div></div></div>''')
E=A['energy'];add('Energy: moderate days versus 100°F.', f'''<table><tr><th>Scenario / all ESTIMATE</th><th>Moderate-weather workday</th><th>100°F Las Vegas stress case</th></tr><tr><td>Base daily loads</td><td colspan="2">{E['base_daily_kwh']:.2f} kWh: editing 0.70; refrigerator 0.80; camera/laptop 0.40; lights 0.20; Starlink 8 h 0.68; pumps/fans 0.20</td></tr><tr><td>HVAC assumption</td><td>0.55 kW average × 8 h = 4.40 kWh</td><td>1.20 kW average × 24 h = 28.80 kWh</td></tr><tr><td>Total demand</td><td>7.38 kWh/day</td><td>31.78 kWh/day</td></tr><tr><td>Solar model</td><td>1.65 kW × 5.5 sun h × 0.75 = 6.81 kWh</td><td>1.65 kW × 6 sun h × 0.70 = 6.93 kWh</td></tr><tr><td>Daily deficit</td><td>~0.57 kWh before laundry / driving charge</td><td>~24.85 kWh before laundry / driving charge</td></tr><tr><td>Generator energy recovery</td><td>~0.20 h mathematical minimum; practical run scheduling longer</td><td>~8.6 h/day at 3.2 kW AC × 90% delivered energy; ~8–11 h working range</td></tr></table><p>Harvest above is conditional on an approved input arrangement accepting the full 1,650 W. One published 50 A input at the panel’s 21.29 V operating point has an approximate 1.06 kW ceiling. Actual clipped kWh requires an irradiance profile and verified controller limits; these full-nameplate harvest values are not validated available energy.</p><p>These are explicit scenarios, not a measured Furrion duty cycle or a cooling-load calculation. Insulation, windshield solar gain, envelope leakage, humidity, occupancy and setpoint are unknown. 18K capacity and indoor comfort at 100°F must be tested.</p><div class="note">1,650 W solar does not support continuous extreme-weather cooling in this stress case. Shade, hotter panels, flat mounting and obstruction can reduce harvest; bifacial gain is not counted.</div>''')
add('Quiet nights, laundry and recharge.', '''<div class="metrics"><div class="metric"><b>7.37 kWh</b><span>ESTIMATED USABLE AC ENERGY</span></div><div class="metric"><b>5.00 kWh</b><span>MILD 8 H NIGHT + BASE</span></div><div class="metric"><b>10.20 kWh</b><span>HOT 8 H NIGHT + BASE</span></div><div class="metric"><b>~5.6 h</b><span>HOT QUIET HVAC WINDOW</span></div></div><div class="grid"><div><h3>Battery budget</h3><p>10.24 kWh nominal × 80% SOC window × 90% inverter efficiency = 7.37 kWh estimated AC energy. Mild night: 8 h × 0.55 kW + 0.60 kWh base = 5.00 kWh. Hot night: 8 h × 1.20 kW + 0.60 = 10.20 kWh; eight hours is not supported in this scenario.</p><p>With 2.3 kW net battery recharge during generator operation, restoring 8.19 kWh DC across the assumed SOC window takes ~3.6 hours before taper/thermal penalties. Charger setting must leave capacity for simultaneous HVAC/other loads.</p></div><div><h3>Scheduling laundry</h3><p>Placeholder wash/dry cycle: 2–4 kWh and 12–20 gal water, both ESTIMATE, not published cycle performance. This can consume ~27–54% of modeled usable AC battery energy and a substantial fraction of the 35 gal fresh/30 gal gray capacity.</p><p>Run laundry during surplus solar, driving/generator charge or shore power after measured cycle data. Pairing 1,300 W laundry with HVAC and RV5 charging requires load budgeting.</p><p>AGS thresholds and quiet hours must be set from measured demand and reserve, with verified generator interface. A mathematical minimum runtime is not a reliable operational schedule.</p></div></div>''')
